-- Transactional business events; no remote telemetry or cross-service foreign keys.
CREATE TABLE identity.event_outbox(event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,event_type text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,aggregate_version text NOT NULL,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'),occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),correlation_id text NOT NULL);
CREATE TABLE identity.event_outbox_delivery(event_id uuid NOT NULL REFERENCES identity.event_outbox ON DELETE CASCADE,target text NOT NULL CHECK(target IN ('identidad','aprendizaje','comunidad','evidencias')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','retry','delivered','deadletter')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,delivered_at timestamptz,last_error text,PRIMARY KEY(event_id,target));
CREATE INDEX event_delivery_due_idx ON identity.event_outbox_delivery(available_at,event_id) WHERE status IN ('pending','retry','processing');
CREATE TABLE identity.event_inbox(source text NOT NULL,event_id uuid NOT NULL,source_sequence bigint NOT NULL,event_type text NOT NULL,request_hash char(64) NOT NULL,correlation_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,PRIMARY KEY(source,event_id));
CREATE TABLE identity.event_projection(source text NOT NULL,aggregate_type text NOT NULL,aggregate_id uuid NOT NULL,source_sequence bigint NOT NULL,aggregate_version text NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL,correlation_id text NOT NULL,PRIMARY KEY(source,aggregate_type,aggregate_id));
CREATE FUNCTION identity.emit_domain_event(event_type text,aggregate_type text,aggregate_id uuid,aggregate_version text,payload jsonb) RETURNS void LANGUAGE plpgsql AS $$ DECLARE event_uuid uuid; BEGIN
 INSERT INTO identity.event_outbox(event_type,aggregate_type,aggregate_id,aggregate_version,payload,correlation_id) VALUES(event_type,aggregate_type,aggregate_id,aggregate_version,payload,COALESCE(NULLIF(current_setting('app.correlation_id',true),''),gen_random_uuid()::text)) RETURNING event_id INTO event_uuid;
 INSERT INTO identity.event_outbox_delivery(event_id,target) SELECT event_uuid,target FROM unnest(ARRAY['aprendizaje','comunidad','evidencias']) target;
END $$;
CREATE FUNCTION identity.account_business_event() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' OR NEW.version IS DISTINCT FROM OLD.version OR NEW.status IS DISTINCT FROM OLD.status THEN PERFORM identity.emit_domain_event('account.changed','account',NEW.id,NEW.version::text,jsonb_build_object('accountId',NEW.id,'status',NEW.status,'version',NEW.version)); END IF; RETURN NEW; END $$;
CREATE TRIGGER account_business_event AFTER INSERT OR UPDATE ON identity.accounts FOR EACH ROW EXECUTE FUNCTION identity.account_business_event();
GRANT SELECT,INSERT,UPDATE,DELETE ON identity.event_outbox,identity.event_outbox_delivery,identity.event_inbox,identity.event_projection TO identity_app;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA identity TO identity_app;
